KINDS = {"dental": DENTAL, "spa": SPA, "school": SCHOOL}


def build(kind, country, base_page):
    """Собирает нишу для страны в формате движка игры."""
    k, L = KINDS[kind], LOC[country]
    cur_word = "тенге" if country == "kz" else "рублей"
    name = k["names"][country]
    about = k["about"].format(city=L["city"])
    rows = k["prices"][country]
    items = [[a, b.format(pay=L["pay"])] for a, b in k["items"]]
    project_text = (f"{name}. {about} Цены: " + "; ".join(f"{a} – {b}" for a, b in rows) + ". " + " ".join(f"{a}. {b}" for a, b in items))
    clients = []
    for c in k["clients"]:
        nm = c["names"][0 if country == "kz" else 1]
        clients.append(dict(id=c["id"], name=nm, sub=c["sub"], first=c["first"],
                            brief=c["brief"].format(name=nm, city=L["city"], cur_word=cur_word)))
    page = dict(base_page)
    page.update(
        label=f"Тренажер-диагностика · {k['title'].lower()} · {L['city']}",
        lead=f"Пять клиентов пишут в мессенджер – в каждой игре разные. Вы отвечаете так, как отвечаете в работе. Каждый слитый клиент "
             f"забирает деньги из кассы, а после каждой переписки – разбор в стиле Анастасии Гавриш.",
        team=f"Вы – {k['role']}. Пять клиентов по очереди пишут вам в мессенджер. Задача – {k['goal']}. Отвечайте так же, как в работе. "
             f"После каждого клиента вы увидите разбор, а итог получит ваш руководитель.",
        task=f"Задача – {k['goal']}: ответить на вопрос, разобраться в ситуации клиента, подобрать вариант и назначить конкретное время.",
        check=f"{k['check']}, {L['cur']}",
        ref=dict(title="услуги, цены и правила", about=about, head=["Услуга", "Цена"], rows=rows, items=items),
    )
    return dict(
        id=f"{kind}_{country}", title=k["title"], country=country, cur=L["cur"], public=True, card=k["card"], clients=clients, per_game=5, rules=COMMON_RULES, project_text=project_text, stages=k["stages"],
        files=[dict(title=t, desc=d) for t, d in k["files"]], max_turns=8, nums=k["nums"][country], project_name=f"{name} ({k['tag']})",
        role=k["role"],
        client_ctx=f"Тебе пишет {k['role']} в {L['msg']}. Ты не помощник и не продавец – ты обычный человек, клиент {L['where']}. "
                   + ("Цены и суммы – в рублях." if country == "ru" else "Цены и суммы – в тенге."),
        files_note="Фото, видео, прайс или сертификат прямо в чате – удобно. Ссылка на сайт или «Актуальное» вместо ответа – неудобно.",
        irritants="«чем могу помочь» после конкретного вопроса, ответ не на твой вопрос, простыни текста, прайс или ссылка вместо подбора, "
                  "просьба перейти в другой канал или оставить номер, звонок без спроса, «окошки» и «неделька», десять вариантов времени, "
                  "вопросы без пояснения зачем, шаблонные фразы, ошибки в тексте, давление",
        win_rule=k["win_rule"], goal=k["goal"], reach=k["reach"], win=k["win"], win_done=k["win_done"], wins=k["wins"],
        win_sys=k["win_sys"], win_verdict=k["win_verdict"], page=page,
    )
